        const newPath = [...path, grid[newRow][newCol]];
        const result = dfs(newRow, newCol, newPath, steps + 1);
        if (result) {
          return result;
        }
      }
    }
    visited[row][col] = false;
    return null;
  }

  let minPath = null;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const path = [grid[i][j]];
      const result = dfs(i, j, path, 1);
      if (result && (!minPath || result.length < minPath.length)) {
        minPath = result;
      }
    }
  }

  return minPath;
}

function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Set();
  const queue = [[grid[0][0], 0, 0]]; // [value, steps, row, col]
  let minPath = [];

  while (queue.length > 0) {
    const [value, steps, row, col] = queue.shift();

    if (steps === k) {
      minPath = [value];
      continue;
    }

    if (steps >= k || value === 0 || visited.has(`${row},${col}`)) continue;

    visited.add(`${row},${col}`);

    for (const [dr, dc] of directions) {
      const newRow = row + dr;
      const newCol = col + dc;

      if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
        queue.push([grid[newRow][newCol], steps + 1, newRow, newCol]);
      }
    }
  }

  return minPath;
}

