  for (let i = 2; i <= Math.sqrt(a); i++) {
    if (a % i === 0) {
      primeCount++;
      if (primeCount > 3) return false;
    }
  }

  if (primeCount === 3) return true;
  return false;
}

function is_multiply_prime(a) {
